import hashlib

def _h(s, salt):
    return int.from_bytes(hashlib.sha1(f"{salt}:{s}".encode()).digest()[:8], "big")

def minhash_sig(text, num_perm=64, k=5):
    shingles = {text[i:i + k] for i in range(len(text) - k + 1)}
    return [min(_h(s, i) for s in shingles) for i in range(num_perm)]

def lsh_candidates(sigs, bands=16):
    rows = len(next(iter(sigs.values()))) // bands
    buckets = {}
    for doc, sig in sigs.items():
        for b in range(bands):
            key = tuple(sig[b * rows:(b + 1) * rows])
            buckets.setdefault(key, []).append(doc)
    return {frozenset(v) for v in buckets.values() if len(v) > 1}

a = "the quick brown fox jumps over the lazy dog " * 4
b = "the quick brown fox leaps over the lazy dog " * 4   # 高相似改写
c = "totally different content about neural networks"
sigs = {"a": minhash_sig(a), "b": minhash_sig(b), "c": minhash_sig(c)}
cand = lsh_candidates(sigs)
assert any({"a", "b"} <= s for s in cand), "a/b 应撞桶"
assert not any("c" in s and len(s) > 1 for s in cand), "c 不应与它们撞"
print("candidates:", [sorted(s) for s in cand])

from collections import Counter

def merge_word(w, pair, new_tok):
    out, i = [], 0
    while i < len(w):
        if i + 1 < len(w) and (w[i], w[i + 1]) == pair:
            out.append(new_tok); i += 2
        else:
            out.append(w[i]); i += 1
    return out

def train_bpe(word_freqs, vocab_size):
    """word_freqs: {'low': 5, ...}；教学版省略预分词正则与字节级编码"""
    words = {tuple(list(w) + ["</w>"]): c for w, c in word_freqs.items()}
    vocab = sorted({t for w in words for t in w})
    merges = []
    while len(vocab) < vocab_size:
        pairs = Counter()
        for w, c in words.items():
            for a, b in zip(w, w[1:]):
                pairs[(a, b)] += c            # 乘词频权重
        if not pairs:
            break
        (a, b), _ = pairs.most_common(1)[0]
        merges.append((a, b))
        vocab.append(a + b)
        words = {tuple(merge_word(list(w), (a, b), a + b)): c
                 for w, c in words.items()}
    return vocab, merges

vocab, merges = train_bpe({"low": 5, "lower": 2, "newest": 6, "widest": 3}, 16)
print("vocab:", vocab)
print("merges:", merges)
assert merges, "应至少学到一个合并"
assert "est</w>" in vocab, "高频后缀应被合并"
